<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Download, FileSpreadsheet, Upload } from 'lucide-vue-next'
import Modal from './Modal.vue'
import Pager from './Pager.vue'
import { api, isArchived, messageOf, notify, ui } from '../api'
interface ImportRow {row?:number;key:string;parent_key:string;name:string;assignee?:string;plan_start?:string;plan_end?:string;estimate_hours?:number;priority?:number;progress?:number;status?:string}
interface Preview {rows:ImportRow[];errors:Array<{row:number;field:string;message:string}>;warnings:Array<string|{row?:number;field?:string;message:string}>;source_hash:string;project_version:number;total:number;filename:string;import_id?:string;confirm_token?:string}
const props=defineProps<{open:boolean;projectId?:string}>();const emit=defineEmits<{close:[];imported:[]}>()
const project=ref(''),file=ref<File>(),input=ref<HTMLInputElement>(),preview=ref<Preview>(),error=ref(''),uploading=ref(false),saving=ref(false),offset=ref(0),showAllErrors=ref(false);const limit=30
const rows=computed(()=>preview.value?.rows.slice(offset.value,offset.value+limit)||[]),target=computed(()=>ui.projects.find(p=>p.id===project.value)),valid=computed(()=>!!preview.value&&!preview.value.errors.length&&preview.value.rows.length>0&&!isArchived(project.value))
watch(()=>props.open,open=>{if(open){project.value=props.projectId||ui.projects.find(p=>!isArchived(p.id))?.id||'';file.value=undefined;preview.value=undefined;error.value='';offset.value=0}})
watch(project,()=>{preview.value=undefined;offset.value=0})
function choose(event:Event){const selected=(event.target as HTMLInputElement).files?.[0];file.value=selected;preview.value=undefined;error.value='';if(selected&&!selected.name.toLowerCase().endsWith('.xlsx')){error.value='请选择 .xlsx 文件；旧版 .xls 请先在 Excel/WPS 中另存为 .xlsx。';file.value=undefined}}
async function inspect(){if(!file.value||!project.value||uploading.value)return;uploading.value=true;error.value='';preview.value=undefined;try{const body=new FormData();body.set('file',file.value);preview.value=await api<Preview>(`/api/projects/${project.value}/import/preview`,{method:'POST',body});offset.value=0;if(preview.value.rows.length!==preview.value.total)error.value='预览条数与服务端总数不一致，已禁用导入；请重新上传。'}catch(e){error.value=messageOf(e)}finally{uploading.value=false}}
async function confirmImport(){if(!valid.value||saving.value||!preview.value||preview.value.rows.length!==preview.value.total)return;saving.value=true;error.value='';try{const result=await api<{total?:number;imported?:number}>(`/api/projects/${project.value}/import`,{method:'POST',body:JSON.stringify({rows:preview.value.rows,source_hash:preview.value.source_hash,project_version:preview.value.project_version,confirm_token:preview.value.confirm_token,...(preview.value.import_id?{import_id:preview.value.import_id}:{})})});notify((result as {already_imported?:boolean}).already_imported?'此文件已导入，已返回原结果，未重复新增':`导入完成，新增 ${result.imported??result.total??preview.value.rows.length} 项任务`);emit('imported');emit('close')}catch(e){error.value=messageOf(e)+'。文件与预览保留，请核对；项目已变化时请重新预览。'}finally{saving.value=false}}
function close(){if(!saving.value&&!uploading.value)emit('close')}
const fieldNames:Record<string,string>={key:'任务标识',parent_key:'上级标识',name:'任务名称',assignee:'负责人',plan_start:'计划开始',plan_end:'计划结束',estimate_hours:'预计工时',priority:'优先级',progress:'进度',status:'状态'}
function warningText(value:Preview['warnings'][number]){return typeof value==='string'?value:`${value.row?'第 '+value.row+' 行：':''}${value.message}`}
</script>
<template><Modal :open="open" title="从 Excel 导入任务" wide @close="close"><div class="modal-body task-import"><p class="input-hint">仅新增任务及层级，不覆盖现有任务。请使用 .xlsx；旧版 .xls 需先另存为 .xlsx。预览通过后再确认写入。</p><a class="button subtle small import-template" href="/api/import-template.xlsx" download><Download :size="15"/>下载导入模板 .xlsx</a><label>导入目标项目<select v-model="project" :disabled="saving||uploading" required><option v-for="p in ui.projects.filter(p=>!isArchived(p.id))" :key="p.id" :value="p.id">{{p.name}}</option></select></label><div class="import-upload"><FileSpreadsheet :size="29"/><div><strong>{{file?.name||'选择任务清单'}}</strong><p>按模板填写任务标识与上级标识，保持层级可追溯。</p></div><button class="button subtle small" :disabled="saving||uploading" @click="input?.click()">选择 .xlsx</button><input ref="input" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden @change="choose"/></div><button class="button primary small" :disabled="!file||!project||uploading||saving" @click="inspect"><Upload :size="15"/>{{uploading?'正在解析与校验…':'上传并预览'}}</button><p v-if="error" class="form-error" role="alert">{{error}}</p><template v-if="preview"><div class="import-overview"><strong>{{preview.filename}} · {{preview.total}} 项任务</strong><span>目标：{{target?.name}} · 项目版本 {{preview.project_version}}</span></div><div v-if="preview.errors.length" class="import-errors" role="alert"><h3>发现 {{preview.errors.length}} 处错误，修正文件后重新预览</h3><ul><li v-for="(item,index) in (showAllErrors?preview.errors:preview.errors.slice(0,20))" :key="index">第 {{item.row}} 行 · {{fieldNames[item.field]||item.field}}：{{item.message}}</li></ul><button v-if="preview.errors.length>20" class="text-button" @click="showAllErrors=!showAllErrors">{{showAllErrors?'收起错误':'显示全部 '+preview.errors.length+' 条错误'}}</button></div><div v-if="preview.warnings.length" class="import-warnings"><h3>{{preview.warnings.length}} 条提示</h3><ul><li v-for="(warning,index) in preview.warnings" :key="index">{{warningText(warning)}}</li></ul></div><div class="table-scroll import-preview"><table><thead><tr><th>Excel 行 / 任务标识</th><th>任务名称</th><th>负责人</th><th>计划日期</th><th>进度 / 工时</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.key+'-'+index"><td><span v-if="row.row" class="import-row-number">第 {{row.row}} 行 · </span>{{row.key}}<small>{{row.parent_key||'顶层任务'}}</small></td><td>{{row.name}}</td><td>{{row.assignee||'未指定'}}</td><td>{{row.plan_start||'未设置'}}<small>至 {{row.plan_end||'未设置'}}</small></td><td>{{row.progress||0}}%<small>{{row.estimate_hours||0}} 小时</small></td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="preview.rows.length" @change="offset=$event"/></template><div class="modal-footer"><span class="muted">{{preview&&!preview.errors.length?'已通过预览校验；确认后一次写入':'预览通过后才能导入'}}</span><button class="button primary" :disabled="!valid||preview?.rows.length!==preview?.total||saving||uploading" @click="confirmImport">{{saving?'正在导入…':'确认新增 '+(preview?.rows.length||0)+' 项任务'}}</button></div></div></Modal></template>
